('<span>Tempasto unterstützen</span>', '<span>Apoyar Tempasto</span>'),
('id="bkSave" hidden>Daten sichern</button><button class="implink" id="bkLoad" hidden>Sicherung laden</button><button class="implink" id="impOpen">Impressum</button>', 'id="bkSave" hidden>Copia de seguridad</button><button class="implink" id="bkLoad" hidden>Restaurar</button><button class="implink" id="impOpen">Aviso legal</button>'),
('<summary><span>Ist mein Teig reif?<small>Wenn die Hefe nicht stimmt oder sich der Plan verschiebt</small></span></summary>', '<summary><span>¿Está lista mi masa?<small>Si la levadura no cuadra o el plan se ha movido</small></span></summary>'),
('for="ckKnead">Fertig geknetet am</label>', 'for="ckKnead">Fin del amasado</label>'),
('id="ckYL">Frischhefe im Teig (g)</label>', 'id="ckYL">Levadura fresca en la masa (g)</label>'),
('<summary><span>Teig retten<small>Zu viel Hefe oder zu weit gegangen</small></span></summary>', '<summary><span>Salvar la masa<small>Demasiada levadura o fermentada de más</small></span></summary>'),
('<li><b>Sofort kalt stellen</b> und portionieren, einzelne Kugeln kühlen schneller durch.</li>', '<li><b>Enfríala ya</b> y divídela; los bollos sueltos se enfrían antes.</li>'),
('<li><b>Kühlschrank</b> auf die kälteste Stufe, Boxen hinten unten, nicht stapeln.</li>', '<li><b>Nevera</b> al nivel más frío, recipientes al fondo y abajo, sin apilar.</li>'),
('<li><b>Einfrieren als Notbremse:</b> Kugeln einzeln in geölte Beutel. Am Vortag in den Kühlschrank (12–24 h), dann 2–3 h bei Raumtemperatur.</li>', '<li><b>Congelar como freno de emergencia:</b> cada bollo en su bolsa aceitada. El día antes, pásalos a la nevera (12–24 h), luego 2–3 h a temperatura ambiente.</li>'),
('<li><b>Nur 1–2 h akklimatisieren</b> statt 3–5 h.</li>', '<li><b>Atemperar solo 1–2 h</b> en lugar de 3–5 h.</li>'),
('<li><b>Übergangenen Teig</b> auf bemehlter Fläche vorsichtig ausziehen, nicht über die Fäuste.</li>', '<li><b>Masa fermentada de más:</b> estírala con cuidado sobre la encimera enharinada, no sobre los puños.</li>'),
('<summary><span>Was ist schiefgelaufen?<small>Teig reißt, Rand flach, Boden blass …</small></span></summary>', '<summary><span>¿Qué ha salido mal?<small>La masa se rompe, borde plano, base pálida…</small></span></summary>'),
('<li><b>Teig reißt beim Ausziehen</b>Meist ist er noch zu kalt. Kugeln 20–30 Minuten länger bei Raumtemperatur stehen lassen. Nicht ziehen, sondern von innen nach außen drücken.</li>', '<li><b>La masa se rompe al estirarla</b>Normalmente aún está demasiado fría. Deja los bollos 20–30 minutos más a temperatura ambiente. No tires, presiona del centro hacia fuera.</li>'),
('<li><b>Teig zieht sich immer wieder zusammen</b>Das Gluten ist noch angespannt. Abgedeckt 15–20 Minuten ruhen lassen, dann geht es.</li>', '<li><b>La masa se encoge</b>El gluten aún está tenso. Déjala reposar tapada 15–20 minutos y listo.</li>'),
('<li><b>Kugeln laufen breit und kleben</b>Sie sind übergangen oder zu warm. Kühler stellen, beim Ausziehen mehr Semola nehmen und zügig backen. Siehe auch „Teig retten“.</li>', '<li><b>Los bollos se aplanan y se pegan</b>Están fermentados de más o demasiado calientes. Ponlos en un sitio más fresco, usa más sémola al estirar y hornea rápido. Mira también «Salvar la masa».</li>'),
('<li><b>Rand bleibt flach</b>Beim Formen wurde die Luft aus dem Rand gedrückt. Einen Fingerbreit Rand nicht anfassen und die Luft von der Mitte nach außen schieben. Auch ein zu kühler Stein bremst den Rand.</li>', '<li><b>El borde se queda plano</b>Al formar sacaste el aire del borde. Deja un dedo de borde sin tocar y empuja el aire del centro hacia fuera. Una piedra poco caliente también frena el borde.</li>'),
('<li><b>Boden bleibt blass oder weich</b>Der Stein ist nicht heiß genug oder der Belag ist zu nass. Länger vorheizen, Fior di Latte abtropfen lassen, weniger Soße.</li>', '<li><b>La base queda pálida o blanda</b>La piedra no está lo bastante caliente o los ingredientes están demasiado húmedos. Precalienta más tiempo, escurre la fior di latte, usa menos salsa.</li>'),
('<li><b>Boden verbrennt, Belag ist noch roh</b>Der Stein ist heißer als die Luft darüber. Flamme höher, Stein kurz abkühlen lassen oder die Pizza zum Schluss anheben.</li>', '<li><b>La base se quema y los ingredientes siguen crudos</b>La piedra está más caliente que el aire de encima. Sube la llama, deja enfriar la piedra un momento o levanta la pizza al final.</li>'),
('<li><b>Pizza klebt an der Schaufel</b>Zu wenig Semola oder zu lange belegt. Schaufel bestreuen, zügig belegen und vor dem Einschießen kurz rütteln.</li>', '<li><b>La pizza se pega a la pala</b>Poca sémola o la pizza lleva demasiado rato montada. Espolvorea la pala, monta la pizza rápido y dale un meneo antes de meterla.</li>'),
('<li><b>Teig nach dem Kneten wärmer als 25 °C</b>Nächstes Mal kälteres Wasser nehmen. Jetzt den Teig gleich nach dem Falten in den Kühlschrank stellen.</li>', '<li><b>Masa a más de 25 °C tras amasar</b>La próxima vez usa agua más fría. Ahora, mete la masa en la nevera justo después de plegarla.</li>'),
('<li><b>Teig geht kaum auf</b>Die Hefe war alt oder der Kühlschrank ist sehr kalt. Kugeln länger bei Raumtemperatur stehen lassen und die Fingerprobe abwarten.</li>', '<li><b>La masa apenas sube</b>La levadura era vieja o la nevera está muy fría. Deja los bollos más tiempo a temperatura ambiente y espera a la prueba del dedo.</li>'),
('<li>Tomaten durch die Flotte Lotte drehen oder mit den Händen zerdrücken. <b>Kein Stabmixer,</b> sonst wird die Soße bitter und hellrot.</li>', '<li>Pasa los tomates por el pasapurés o aplástalos a mano. <b>Nada de batidora,</b> o la salsa se vuelve amarga y de un rojo pálido.</li>'),
('aria-label="Tomatendose mit Herkunftskürzel, Abfüllcode und DOP-Siegel"', 'aria-label="Lata de tomate con código de origen, código de envasado y sello DOP"'),
